74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
81	     * owner's id, customer code, registration date and membership level, so the create side-effect
82	     * can be audited independently of the application log.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    /**
95	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
96	     * and a domain containing at least one dot, with no whitespace in any segment.
97	     */
98	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
99	
100	    /**
101	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
102	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
103	     * {@code '@'}) is rejected with a 400 Bad Request.
104	     */
105	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
106	        "mailinator.com",
107	        "tempmail.com",
108	        "guerrillamail.com");
109	
110	    /**
111	     * Required national-number length per E.164 country code. A normalized telephone whose country
112	     * code appears here must carry exactly this many national digits after the code; Australia
113	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
114	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
115	     */
116	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
117	
118	    /**
119	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
120	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
121	     */
122	    private static final int MAX_OWNERS_PER_CITY = 50;
123	
124	    /**
125	     * Maximum number of owners that may be registered on a single day (by registration date). A create
126	     * attempted once this many owners already carry today's registration date is rejected with a
127	     * 429 Too Many Requests.
128	     */
129	    private static final int MAX_OWNERS_PER_DAY = 100;
130	
131	    /**
132	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
133	     * owners already carry the new owner's registration date, the created owner is flagged
134	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
135	     */
136	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
137	
138	    /**
139	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
140	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
141	     */
142	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
143	        "ST", "STREET",
144	        "RD", "ROAD",
145	        "AVE", "AVENUE");
146	
147	    /**
148	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
149	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
150	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
151	     * 4-digit postcode.
152	     */
153	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
154	        "NSW", new int[] {2000, 2099},
155	        "VIC", new int[] {3000, 3099},
156	        "QLD", new int[] {4000, 4099});
157	
158	    /**
159	     * Name of the request header that carries the client-supplied idempotency key for an owner create.
160	     * When a create repeats with a key already seen, the originally created owner is returned with
161	     * {@code 200 OK} instead of a second owner being created.
162	     */
163	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
164	
165	    /**
166	     * Remembers, per idempotency key, the id of the owner created by the first request that carried that
167	     * key, so a later create repeating the same key can return the original owner instead of creating a
168	     * duplicate. The key space is the client-supplied {@code Idempotency-Key} header value.
169	     */
170	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
171	
172	    public OwnerRestControllerV1(ClinicService clinicService,
173	                                 OwnerMapper ownerMapper,
174	                                 PetMapper petMapper,
175	                                 VisitMapper visitMapper) {
176	        this.clinicService = clinicService;
177	        this.ownerMapper = ownerMapper;
178	        this.petMapper = petMapper;
179	        this.visitMapper = visitMapper;
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
185	        Collection<Owner> owners;
186	        if (lastName != null) {
187	            owners = this.clinicService.findOwnerByLastName(lastName);
188	        } else {
189	            owners = this.clinicService.findAllOwners();
190	        }
191	        if (owners.isEmpty()) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
200	        Owner owner = this.clinicService.findOwnerById(ownerId);
201	        if (owner == null) {
202	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	        }
204	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
210	        String idempotencyKey = currentIdempotencyKey();
211	        OwnerDto replayed = replayIfSeen(idempotencyKey);
212	        if (replayed != null) {
213	            return new ResponseEntity<>(replayed, HttpStatus.OK);
214	        }
215	        validateRequiredFields(ownerFieldsDto);
216	        HttpHeaders headers = new HttpHeaders();
217	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
218	        rejectFutureRegistrationDate(owner.getRegistrationDate());
219	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
220	        owner.setRegistrationDate(registrationDate);
221	        requireDailyCapacity(registrationDate);
222	        requireCityHasCapacity(owner.getCity());
223	        validatePostcode(owner);
224	        applyAddress(owner, ownerFieldsDto);
225	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
226	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
227	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
228	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
229	        requireUniqueIdentity(owner);
230	        flagPossibleDuplicate(owner, declaredHouseholdMember);
231	        owner.setCustomerCode(deduplicateCustomerCode(owner.buildCustomerCode()));
232	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
233	        stampHouseholdSize(owner);
234	        capMembershipLevelToHousehold(owner);
235	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
236	        this.clinicService.saveOwner(owner);
237	        rememberCreate(idempotencyKey, owner);
238	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
239	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
240	            owner.getMembershipNumber());
241	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
242	        headers.setLocation(UriComponentsBuilder.newInstance()
243	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
244	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
245	    }
246	
247	    /**
248	     * Reads the client-supplied idempotency key from the current request's {@code Idempotency-Key}
249	     * header. Returns {@code null} when the header is absent or blank (the create is not idempotent),
250	     * or when no servlet request is bound to the current thread.
251	     *
252	     * <p>The header is read from the bound request rather than taken as a {@code @RequestHeader} method
253	     * parameter because {@code addOwner}'s signature is fixed by the generated {@link OwnersApi}
254	     * interface and cannot carry an extra parameter.
255	     *
256	     * @return the trimmed idempotency key, or {@code null} when none was supplied
257	     */
258	    private String currentIdempotencyKey() {
259	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
260	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
261	            if (StringUtils.hasText(key)) {
262	                return key.trim();
263	            }
264	        }
265	        return null;
266	    }
267	
268	    /**
269	     * Returns the owner originally created under the given idempotency key, so a create repeating a
270	     * key already seen replays the first result instead of creating a duplicate. Yields {@code null}
271	     * when there is no key, the key has not been seen, or the remembered owner no longer exists (in
272	     * which case the create proceeds normally).
273	     *
274	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
275	     * @return the originally created owner as a DTO, or {@code null} when there is nothing to replay
276	     */
277	    private OwnerDto replayIfSeen(String idempotencyKey) {
278	        if (idempotencyKey == null) {
279	            return null;
280	        }
281	        Integer existingId = idempotentCreates.get(idempotencyKey);
282	        if (existingId == null) {
283	            return null;
284	        }
285	        Owner existing = this.clinicService.findOwnerById(existingId);
286	        return existing == null ? null : ownerMapper.toOwnerDto(existing);
287	    }
288	
289	    /**
290	     * Remembers the id of a just-created owner against the idempotency key that produced it, so a later
291	     * create repeating the same key can be replayed by {@link #replayIfSeen}. A {@code null} key (the
292	     * create was not idempotent) is ignored.
293	     *
294	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
295	     * @param owner the owner that was just created and saved
296	     */
297	    private void rememberCreate(String idempotencyKey, Owner owner) {
298	        if (idempotencyKey != null) {
299	            idempotentCreates.put(idempotencyKey, owner.getId());
300	        }
301	    }
302	
303	    /**
304	     * Rejects a create whose supplied registration date is later than the server's current date. A
305	     * registration may be back-dated but never post-dated, so a future date is treated as a client
306	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
307	     * server date.
308	     *
309	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
310	     *     client omitted it
311	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
312	     */
313	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
314	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
315	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
316	        }
317	    }
318	
319	    /**
320	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
321	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
322	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
323	     * existed prior to this create.
324	     *
325	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
326	     *     a business day
327	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
328	     *     registered on that business day
329	     */
330	    private void requireDailyCapacity(LocalDate registrationDate) {
331	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
332	            throw new DailyOwnerLimitException(registrationDate);
333	        }
334	    }
335	
336	    /**
337	     * Counts the existing owners whose registration date equals the given business-day date. This is
338	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
339	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
340	     * the bulk-signup warning.
341	     *
342	     * @param registrationDate the effective business-day registration date to count against
343	     * @return the number of pre-existing owners registered on that date
344	     */
345	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
346	        return this.clinicService.findAllOwners().stream()
347	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
348	            .count();
349	    }
350	
351	    /**
352	     * Rejects an owner whose city already contains the maximum allowed number of owners
353	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
354	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
355	     * create.
356	     *
357	     * @param city the city of the owner being created
358	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
359	     */
360	    private void requireCityHasCapacity(String city) {
361	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
362	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
363	            .count();
364	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
365	            throw new CityOwnerLimitException(city);
366	        }
367	    }
368	
369	    /**
370	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
371	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
372	     * schema) that must fall within the inclusive range permitted for the region derived from the
373	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
374	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
375	     *
376	     * @param owner the owner being created, with its city and postcode set
377	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
378	     */
379	    private void validatePostcode(Owner owner) {
380	        String postcode = owner.getPostcode();
381	        if (postcode == null) {
382	            return;
383	        }
384	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
385	        if (range == null) {
386	            return;
387	        }
388	        int value = Integer.parseInt(postcode);
389	        if (value < range[0] || value > range[1]) {
390	            throw new InvalidOwnerFieldsException(List.of("postcode"));
391	        }
392	    }
393	
394	    /**
395	     * Counts the existing owners that already share the given first name and last name, compared
396	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
397	     * owners that existed prior to this create.
398	     *
399	     * @param firstName the first name of the owner being created
400	     * @param lastName the last name of the owner being created
401	     * @return the number of pre-existing namesakes
402	     */
403	    private int countNamesakes(String firstName, String lastName) {
404	        return (int) this.clinicService.findAllOwners().stream()
405	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
406	                && equalsIgnoreCase(existing.getLastName(), lastName))
407	            .count();
408	    }
409	
410	    /**
411	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
412	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
413	     *
414	     * @param a the first value, possibly {@code null}
415	     * @param b the second value, possibly {@code null}
416	     * @return whether the values are equal ignoring case
417	     */
418	    private boolean equalsIgnoreCase(String a, String b) {
419	        return a == null ? b == null : a.equalsIgnoreCase(b);
420	    }
421	
422	    /**
423	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
424	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
425	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
426	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
427	     *
428	     * @param ownerFieldsDto the submitted owner fields
429	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
430	     */
431	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
432	        List<String> invalidFields = new ArrayList<>();
433	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
434	            invalidFields.add("firstName");
435	        }
436	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
437	            invalidFields.add("lastName");
438	        }
439	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddressLine1()))
440	            && !StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
441	            invalidFields.add("address");
442	        }
443	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
444	            invalidFields.add("city");
445	        }
446	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
447	            invalidFields.add("telephone");
448	        }
449	        if (!invalidFields.isEmpty()) {
450	            throw new InvalidOwnerFieldsException(invalidFields);
451	        }
452	    }
453	
454	    /**
455	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
456	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
457	     * what gets stored and returned.
458	     *
459	     * @param telephone the raw telephone value from the request
460	     * @return the normalized E.164 telephone number
461	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
462	     */
463	    private String normalizeTelephone(String telephone) {
464	        String e164 = toE164(telephone);
465	        if (e164 == null) {
466	            throw new InvalidOwnerFieldsException(List.of("telephone"));
467	        }
468	        return e164;
469	    }
470	
471	    /**
472	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
473	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
474	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
475	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
476	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
477	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
478	     *
479	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
480	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
481	     *
482	     * @param telephone the raw telephone value, possibly {@code null}
483	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
484	     */
485	    private String toE164(String telephone) {
486	        if (telephone == null) {
487	            return null;
488	        }
489	        String cleaned = telephone.replaceAll("[ \\-()]", "");
490	        String digits;
491	        if (cleaned.startsWith("+")) {
492	            digits = cleaned.substring(1);
493	        } else {
494	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
495	            digits = "61" + national;
496	        }
497	        if (!digits.matches("[0-9]{8,15}")) {
498	            return null;
499	        }
500	        if (!nationalNumberLengthValid(digits)) {
501	            return null;
502	        }
503	        return "+" + digits;
504	    }
505	
506	    /**
507	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
508	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
509	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
510	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
511	     * accepted, leaving only the generic total-length rule to apply.
512	     *
513	     * @param digits the E.164 digits without the leading {@code '+'}
514	     * @return {@code true} if the national-number length matches the country code's requirement
515	     */
516	    private boolean nationalNumberLengthValid(String digits) {
517	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
518	            String code = entry.getKey();
519	            if (digits.startsWith(code)) {
520	                return digits.length() - code.length() == entry.getValue();
521	            }
522	        }
523	        return true;
524	    }
525	
526	    /**
527	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
528	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
529	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
530	     * returned lower-cased.
531	     *
532	     * @param email the raw email value from the request, possibly {@code null}
533	     * @return the lower-cased email, or {@code null} when none was supplied
534	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
535	     *     its domain is on the disposable-domain blocklist
536	     */
537	    private String normalizeEmail(String email) {
538	        if (!StringUtils.hasText(email)) {
539	            return null;
540	        }
541	        String trimmed = email.trim();
542	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
543	            throw new InvalidOwnerFieldsException(List.of("email"));
544	        }
545	        String normalized = trimmed.toLowerCase(Locale.ROOT);
546	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
547	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
548	            throw new InvalidOwnerFieldsException(List.of("email"));
549	        }
550	        return normalized;
551	    }
552	
553	    /**
554	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
555	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
556	     * owner's normalized telephone, email (empty when absent) and household id joined with
557	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
558	     * owner's. Because the telephone is part of the key, two members of the same household
559	     * (same {@code householdId}) with different telephones have different identity keys and are both
560	     * allowed.
561	     *
562	     * @param owner the owner being created, with its normalized telephone, email and household id set
563	     * @throws DuplicateIdentityException if another owner already has this identity key
564	     */
565	    private void requireUniqueIdentity(Owner owner) {
566	        String identityKey = owner.getIdentityKey();
567	        boolean inUse = this.clinicService.findAllOwners().stream()
568	            .filter(existing -> !existing.isDeleted())
569	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
570	        if (inUse) {
571	            throw new DuplicateIdentityException(identityKey);
572	        }
573	    }
574	
575	    /**
576	     * De-duplicates a newly computed customer code against the codes already held by existing owners.
577	     * When the computed code is unique it is returned unchanged. When it collides with an existing
578	     * owner's {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more
579	     * that makes the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and
580	     * so on), and that de-duplicated code is returned.
581	     *
582	     * @param customerCode the freshly computed customer code to de-duplicate
583	     * @return a customer code not held by any existing owner
584	     */
585	    private String deduplicateCustomerCode(String customerCode) {
586	        Set<String> inUse = this.clinicService.findAllOwners().stream()
587	            .map(Owner::getCustomerCode)
588	            .filter(Objects::nonNull)
589	            .collect(Collectors.toSet());
590	        if (!inUse.contains(customerCode)) {
591	            return customerCode;
592	        }
593	        int n = 2;
594	        String candidate;
595	        do {
596	            candidate = customerCode + "-" + n;
597	            n++;
598	        } while (inUse.contains(candidate));
599	        return candidate;
600	    }
601	
602	    /**
603	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
604	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
605	     * but it shares an existing owner's last name (compared case-insensitively) and postcode (both
606	     * present and equal) while carrying a different normalized telephone. When such an existing owner is
607	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
608	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
609	     * is false and {@code possibleDuplicateOf} is left unset.
610	     *
611	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
612	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
613	     *
614	     * @param owner the owner being created, with its normalized telephone and postcode set
615	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
616	     */
617	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
618	        if (declaredHouseholdMember || owner.getPostcode() == null) {
619	            owner.setPossibleDuplicate(false);
620	            return;
621	        }
622	        Integer matchId = this.clinicService.findAllOwners().stream()
623	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
624	                && owner.getPostcode().equals(existing.getPostcode())
625	                && !owner.getTelephone().equals(existing.getTelephone()))
626	            .map(Owner::getId)
627	            .min(Integer::compareTo)
628	            .orElse(null);
629	        owner.setPossibleDuplicate(matchId != null);
630	        owner.setPossibleDuplicateOf(matchId);
631	    }
632	
633	    /**
634	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
635	     * the household - the existing owners that share the deterministic {@code householdId} and the new
636	     * one - so the shared size can be read back from any of them. The count is the number of existing
637	     * members plus the owner being created.
638	     *
639	     * @param owner the owner being created, with its deterministic {@code householdId} already set
640	     */
641	    private void stampHouseholdSize(Owner owner) {
642	        List<Owner> members = householdMembers(owner);
643	        int householdSize = members.size() + 1;
644	        owner.setHouseholdSize(householdSize);
645	        for (Owner member : members) {
646	            member.setHouseholdSize(householdSize);
647	            this.clinicService.saveOwner(member);
648	        }
649	    }
650	
651	    /**
652	     * The existing owners that belong to the same household as the given owner - those that share its
653	     * deterministic {@code householdId}. This is the single definition of "who is in this household",
654	     * shared by the household-size stamp and the membership-level cap. The owner being created is not
655	     * among them (it has not been saved yet); soft-deleted owners are included, so callers that need
656	     * only live members filter them out themselves.
657	     *
658	     * @param owner the owner being created, with its deterministic {@code householdId} already set
659	     * @return the existing same-household owners
660	     */
661	    private List<Owner> householdMembers(Owner owner) {
662	        String householdId = owner.getHouseholdId();
663	        return this.clinicService.findAllOwners().stream()
664	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
665	            .toList();
666	    }
667	
668	    /**
669	     * Caps the new owner's membership level so it cannot exceed one above the current maximum
670	     * membership level among the existing members of its household - the non-deleted owners that share
671	     * the deterministic {@code householdId}. The new owner's level is lowered to that ceiling only when
672	     * its derived level sits above it; otherwise it is left to be derived normally. When the household
673	     * has no existing member no cap applies and the level is left untouched.
674	     *
675	     * @param owner the owner being created, with its deterministic {@code householdId} and
676	     *     {@code householdSize} already set
677	     */
678	    private void capMembershipLevelToHousehold(Owner owner) {
679	        OptionalInt maxMemberLevel = householdMembers(owner).stream()
680	            .filter(existing -> !existing.isDeleted())
681	            .mapToInt(Owner::getMembershipLevel)
682	            .max();
683	        if (maxMemberLevel.isEmpty()) {
684	            return;
685	        }
686	        int cap = maxMemberLevel.getAsInt() + 1;
687	        if (owner.getMembershipLevel() > cap) {
688	            owner.setMembershipLevel(cap);
689	        }
690	    }
691	
692	    /**
693	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
694	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
695	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
696	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
697	     * shares a last name and postcode computes the same identifier and therefore the same household.
698	     *
699	     * @param lastName the last name of the household
700	     * @param postcode the postcode of the household, possibly {@code null}
701	     * @return the 12-character upper-case hex household identifier
702	     */
703	    private String computeHouseholdId(String lastName, String postcode) {
704	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
705	        try {
706	            byte[] digest = MessageDigest.getInstance("SHA-256")
707	                .digest(key.getBytes(StandardCharsets.UTF_8));
708	            StringBuilder hex = new StringBuilder(12);
709	            for (int i = 0; i < 6; i++) {
710	                hex.append(String.format("%02X", digest[i]));
711	            }
712	            return hex.toString();
713	        } catch (NoSuchAlgorithmException e) {
714	            throw new IllegalStateException("SHA-256 algorithm not available", e);
715	        }
716	    }
717	
718	    /**
719	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
720	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
721	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
722	     *
723	     * @param value the raw value, possibly {@code null}
724	     * @return the normalized value
725	     */
726	    private String normalizeForHousehold(String value) {
727	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
728	    }
729	
730	    /**
731	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
732	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
733	     * value yields an empty string.
734	     *
735	     * @param value the raw value, possibly {@code null}
736	     * @return the trimmed, whitespace-collapsed value
737	     */
738	    private String collapseWhitespace(String value) {
739	        if (value == null) {
740	            return "";
741	        }
742	        return value.trim().replaceAll("\\s+", " ");
743	    }
744	
745	    /**
746	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
747	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
748	     * is upper-cased, and common street-type abbreviations are expanded as whole words
749	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
750	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
751	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
752	     *
753	     * @param address the raw address value, possibly {@code null}
754	     * @return the normalized address
755	     */
756	    private String normalizeAddress(String address) {
757	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
758	        if (collapsed.isEmpty()) {
759	            return "";
760	        }
761	        String[] tokens = collapsed.split(" ");
762	        StringBuilder normalized = new StringBuilder();
763	        for (int i = 0; i < tokens.length; i++) {
764	            if (i > 0) {
765	                normalized.append(' ');
766	            }
767	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
768	        }
769	        return normalized.toString();
770	    }
771	
772	    /**
773	     * Applies the owner's address from the request, preferring the structured form over the flat one.
774	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
775	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
776	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
777	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
778	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
779	     * the structured address when present, falling back to the flat address.
780	     *
781	     * @param owner the owner being created
782	     * @param ownerFieldsDto the submitted owner fields
783	     */
784	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
785	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
786	        if (StringUtils.hasText(line1)) {
787	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
788	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
789	            owner.setAddressLine1(line1);
790	            owner.setAddressLine2(normalizedLine2);
791	            owner.setAddress(composeAddress(line1, normalizedLine2));
792	        } else {
793	            owner.setAddressLine1(null);
794	            owner.setAddressLine2(null);
795	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
796	        }
797	    }
798	
799	    /**
800	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
801	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
802	     * appended when the second line is present.
803	     *
804	     * @param line1 the normalized first address line
805	     * @param line2 the normalized second address line, or {@code null} when absent
806	     * @return the composed address string
807	     */
808	    private String composeAddress(String line1, String line2) {
809	        return line2 == null ? line1 : line1 + " " + line2;
810	    }
811	
812	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
813	    @Override
814	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
815	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
816	        if (currentOwner == null) {
817	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
818	        }
819	        currentOwner.setAddress(ownerFieldsDto.getAddress());
820	        currentOwner.setCity(ownerFieldsDto.getCity());
821	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
822	        currentOwner.setLastName(ownerFieldsDto.getLastName());
823	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
824	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
825	        this.clinicService.saveOwner(currentOwner);
826	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
827	    }
828	
829	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
830	    @Transactional
831	    @Override
832	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
833	        Owner owner = this.clinicService.findOwnerById(ownerId);
834	        if (owner == null) {
835	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
836	        }
837	        owner.setDeleted(true);
838	        this.clinicService.saveOwner(owner);
839	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
840	    }
841	
842	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
843	    @Override
844	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
845	        Owner owner = this.clinicService.findOwnerById(ownerId);
846	        if (owner == null) {
847	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
848	        }
849	        HttpHeaders headers = new HttpHeaders();
850	        Pet pet = petMapper.toPet(petFieldsDto);
851	        owner.setId(ownerId);
852	        pet.setOwner(owner);
853	        pet.getType().setName(null);
854	        this.clinicService.savePet(pet);
855	        PetDto petDto = petMapper.toPetDto(pet);
856	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
857	            .buildAndExpand(pet.getId()).toUri());
858	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
859	    }
860	
861	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
862	    @Override
863	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
864	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
865	        if (currentOwner != null) {
866	            Pet currentPet = this.clinicService.findPetById(petId);
867	            if (currentPet != null) {
868	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
869	                currentPet.setName(petFieldsDto.getName());
870	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
871	                this.clinicService.savePet(currentPet);
872	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
873	            }
874	        }
875	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
876	    }
877	
878	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
879	    @Override
880	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
881	        HttpHeaders headers = new HttpHeaders();
882	        Visit visit = visitMapper.toVisit(visitFieldsDto);
883	        Pet pet = new Pet();
884	        pet.setId(petId);
885	        visit.setPet(pet);
886	        this.clinicService.saveVisit(visit);
887	        VisitDto visitDto = visitMapper.toVisitDto(visit);
888	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
889	            .buildAndExpand(visit.getId()).toUri());
890	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
891	    }
892	
893	
894	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
895	    @Override
896	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
897	        Owner owner = this.clinicService.findOwnerById(ownerId);
898	        if (owner != null) {
899	            Pet pet = owner.getPet(petId);
900	            if (pet != null) {
901	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
902	            }
903	        }
904	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
905	    }
906	}
