207	    /**
208	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
209	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
210	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
211	     * split by taking its leading digit as the (minimal) country code.
212	     */
213	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
214	
215	    /**
216	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
217	     * single space, then the national digits grouped in threes from the left (e.g. the stored
218	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
219	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
220	     * digit string.
221	     *
222	     * @return the human-readable telephone, or the stored value when it cannot be formatted
223	     */
224	    public String getTelephoneDisplay() {
225	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
226	            return this.telephone;
227	        }
228	        String digits = this.telephone.substring(1);
229	        String countryCode = extractCountryCode(digits);
230	        String national = digits.substring(countryCode.length());
231	        StringBuilder display = new StringBuilder("+").append(countryCode);
232	        for (int i = 0; i < national.length(); i += 3) {
233	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
234	        }
235	        return display.toString();
236	    }
237	
238	    /**
239	     * Splits the country code off an E.164 digit string (country code followed by national digits,
240	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
241	     * whose required national-number length matches the remaining digits is preferred; failing that,
242	     * the leading digit is used as the country code.
243	     *
244	     * @param digits the E.164 digits without the leading {@code '+'}
245	     * @return the country-code portion of {@code digits}
246	     */
247	    private static String extractCountryCode(String digits) {
248	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
249	            String code = entry.getKey();
250	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
251	                return code;
252	            }
253	        }
254	        return digits.substring(0, 1);
255	    }
