295	        int years = Period.between(this.birthDate, asAt).getYears();
296	        if (years < 18) {
297	            return "MINOR";
298	        }
299	        if (years < 65) {
300	            return "ADULT";
301	        }
302	        return "SENIOR";
303	    }
