328	    /**
329	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the last two digits of
330	     * the fiscal year of the {@link #getRegistrationDate() business-day-adjusted registration date}.
331	     * The fiscal year starts on 1 July and is named by the calendar year in which it ends, so a
332	     * registration date on or after 1 July belongs to the following calendar year's fiscal year
333	     * (e.g. {@code 2026-07-01} is {@code 'FY27'}) while an earlier date stays in the current one
334	     * (e.g. {@code 2026-06-15} is {@code 'FY26'}). Returns {@code null} when the registration date is
335	     * absent.
336	     *
337	     * @return the fiscal year, or {@code null} when the registration date is absent
338	     */
339	    public String getFiscalYear() {
340	        if (this.registrationDate == null) {
341	            return null;
342	        }
343	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
344	    }
345	
346	    /**
347	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
348	     * is named by the calendar year in which it ends: a date in July through December belongs to the
349	     * next calendar year's fiscal year, while January through June stays in the current one.
350	     *
351	     * @param date the date to classify
352	     * @return the fiscal year as a four-digit calendar year
353	     */
354	    private static int fiscalYearOf(LocalDate date) {
355	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
356	    }
357	
358	    /**
359	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
360	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
361	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
362	     *
363	     * @return the Luhn check digit, or {@code null} when the customer code is absent
364	     */
365	    public Integer getCheckDigit() {
366	        if (this.customerCode == null) {
367	            return null;
368	        }
369	        int sum = 0;
370	        boolean dbl = true;
371	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
372	            char c = this.customerCode.charAt(i);
373	            if (c < '0' || c > '9') {
374	                continue;
375	            }
376	            int d = c - '0';
377	            if (dbl) {
378	                d *= 2;
379	                if (d > 9) {
380	                    d -= 9;
381	                }
382	            }
383	            sum += d;
384	            dbl = !dbl;
385	        }
386	        return (10 - (sum % 10)) % 10;
387	    }
388	
389	    /**
390	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
391	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
392	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
393	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
394	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
395	     * tenure, the tenure points are never awarded at create time.
396	     *
397	     * @return the membership points, a non-negative integer
398	     */
399	    public Integer getMembershipPoints() {
400	        int points = 0;
401	        boolean hasEmail = this.email != null && !this.email.isBlank();
402	        if (hasEmail) {
403	            points += 2;
404	        }
405	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
406	        if (hasNoNamesakes) {
407	            points += 1;
408	        }
409	        if (this.householdSize != null && this.householdSize >= 3) {
410	            points += 2;
411	        }
412	        Long tenureFiscalYears = getTenureFiscalYears();
413	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
414	            points += 3;
415	        }
416	        return points;
417	    }
418	
419	    /**
420	     * The owner's numeric membership level. This is normally derived from the
421	     * {@link #getMembershipPoints() membership points} (see {@link #deriveMembershipLevel()}), but a
422	     * household-level cap applied at create time may store a lower value here; when such a capped level
423	     * has been stored it is returned in preference to the derived one.
424	     *
425	     * @return the membership level, an integer from 1 to 4
426	     */
427	    public Integer getMembershipLevel() {
428	        if (this.membershipLevel != null) {
429	            return this.membershipLevel;
430	        }
431	        return deriveMembershipLevel();
432	    }
433	
434	    public void setMembershipLevel(Integer membershipLevel) {
435	        this.membershipLevel = membershipLevel;
436	    }
437	
438	    /**
439	     * The owner's numeric membership level derived purely from the {@link #getMembershipPoints()
440	     * membership points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and
441	     * level 4 for 6 or more points. This is the uncapped level, before any household-level cap.
442	     *
443	     * @return the derived membership level, an integer from 1 to 4
444	     */
445	    public Integer deriveMembershipLevel() {
446	        int points = getMembershipPoints();
447	        if (points <= 1) {
448	            return 1;
449	        }
450	        if (points <= 3) {
451	            return 2;
452	        }
453	        if (points <= 5) {
454	            return 3;
455	        }
456	        return 4;
457	    }
458	
459	    /**
460	     * The owner's tenure in elapsed fiscal years, the number of fiscal-year boundaries crossed from
461	     * the {@link #getFiscalYear() fiscal year} of the {@link #getRegistrationDate() registration date}
462	     * to the fiscal year of the server's current date (the fiscal year starts on 1 July). An owner
463	     * registered in the current fiscal year has a tenure of 0; one elapsed fiscal year or more is what
464	     * awards the tenure membership points. Returns {@code null} when no registration date has been set
465	     * yet.
466	     *
467	     * @return the tenure in elapsed fiscal years, or {@code null} when the registration date is absent
468	     */
469	    public Long getTenureFiscalYears() {
470	        if (this.registrationDate == null) {
471	            return null;
472	        }
473	        return (long) (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
474	    }
475	
476	    /**
477	     * The owner's locality, the canonical region string. Once the owner has a
478	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
479	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
480	     * source of truth. Before the customer code is assigned (for example while a create is still
481	     * validating the postcode) it falls back to the region the code will be built from: the
482	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
483	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
484	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
485	     *
486	     * @return the canonical region string, or {@code 'UNKNOWN'}
487	     */
488	    public String getLocality() {
489	        if (this.customerCode != null) {
490	            int dash = this.customerCode.indexOf('-');
491	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
492	        }
493	        return deriveRegion();
494	    }
495	
496	    /**
497	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
498	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
499	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
500	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
501	     *
502	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
503	     */
504	    public String getTimezone() {
505	        return REGION_TIMEZONE.get(getLocality());
506	    }
507	
508	    /**
509	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
510	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
511	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
512	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
513	     * the same region for known cities but disambiguates cities that share a name.
514	     *
515	     * @return the canonical region string, or {@code 'UNKNOWN'}
516	     */
517	    private String deriveRegion() {
518	        String region = regionFromPostcode();
519	        if (region != null) {
520	            return region;
521	        }
522	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
523	    }
524	
525	    /**
526	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
527	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
528	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
529	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
530	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
531	     * owner's region, telephone and last name. Call this once at create time and store the result via
532	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
533	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
534	     *
535	     * @return the assembled customer code
536	     */
537	    public String buildCustomerCode() {
538	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
539	    }
540	
541	    /**
542	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
543	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
544	     *
545	     * @param value the value to hash
546	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
547	     */
548	    private static String sha256Hex8(String value) {
549	        try {
550	            byte[] digest = MessageDigest.getInstance("SHA-256")
551	                .digest(value.getBytes(StandardCharsets.UTF_8));
552	            StringBuilder hex = new StringBuilder(8);
553	            for (int i = 0; i < 4; i++) {
554	                hex.append(String.format("%02X", digest[i]));
555	            }
556	            return hex.toString();
557	        }
558	        catch (NoSuchAlgorithmException e) {
559	            throw new IllegalStateException("SHA-256 algorithm not available", e);
560	        }
561	    }
562	
563	    /**
564	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
565	     * absent, not a 4-digit number, or in no known range.
566	     *
567	     * @return the matching region, or {@code null}
568	     */
569	    private String regionFromPostcode() {
570	        if (this.postcode == null) {
571	            return null;
572	        }
573	        int value;
574	        try {
575	            value = Integer.parseInt(this.postcode.trim());
576	        }
577	        catch (NumberFormatException ex) {
578	            return null;
579	        }
580	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
581	            int[] range = entry.getValue();
582	            if (value >= range[0] && value <= range[1]) {
583	                return entry.getKey();
584	            }
585	        }
586	        return null;
587	    }
588	
589	    /**
590	     * The owner's preferred contact channel, derived from the owner's details. Returns
591	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
592	     *
593	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
594	     */
595	    public String getContactPreference() {
596	        boolean hasEmail = this.email != null && !this.email.isBlank();
597	        return hasEmail ? "EMAIL" : "PHONE";
598	    }
599	
600	    /**
601	     * The owner's identity key, the single derived value used for duplicate detection. It is the
602	     * owner's normalized telephone, email (empty when absent) and household id joined with
603	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
604	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
605	     * are equal, so two members of the same household with different telephones differ here and are
606	     * both allowed.
607	     *
608	     * @return the derived identity key
609	     */
610	    public String getIdentityKey() {
611	        return (this.telephone == null ? "" : this.telephone) + "|"
612	            + (this.email == null ? "" : this.email) + "|"
613	            + (this.householdId == null ? "" : this.householdId);
614	    }
615	
616	    public String getHouseholdId() {
617	        return this.householdId;
618	    }
619	
620	    public void setHouseholdId(String householdId) {
621	        this.householdId = householdId;
622	    }
623	
624	    public Integer getNamesakeCount() {
625	        return this.namesakeCount;
626	    }
627	
628	    public void setNamesakeCount(Integer namesakeCount) {
629	        this.namesakeCount = namesakeCount;
630	    }
631	
632	    public Integer getHouseholdSize() {
633	        return this.householdSize;
634	    }
635	
636	    public void setHouseholdSize(Integer householdSize) {
637	        this.householdSize = householdSize;
638	    }
639	
640	    public String getPostcode() {
641	        return this.postcode;
642	    }
643	
644	    public void setPostcode(String postcode) {
645	        this.postcode = postcode;
646	    }
647	
648	    public Boolean getBulkSignupWarning() {
649	        return this.bulkSignupWarning;
650	    }
651	
652	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
653	        this.bulkSignupWarning = bulkSignupWarning;
654	    }
655	
656	    public Boolean getPossibleDuplicate() {
657	        return this.possibleDuplicate;
658	    }
659	
660	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
661	        this.possibleDuplicate = possibleDuplicate;
662	    }
663	
664	    public Integer getPossibleDuplicateOf() {
665	        return this.possibleDuplicateOf;
666	    }
667	
668	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
669	        this.possibleDuplicateOf = possibleDuplicateOf;
670	    }
671	
672	    /**
673	     * Whether this owner has been soft-deleted. A newly created owner is not deleted
674	     * ({@code false}); the DELETE endpoint marks the owner deleted ({@code true}) while retaining the
675	     * row, and the create endpoint's duplicate and identity checks ignore owners flagged deleted.
676	     *
677	     * @return whether the owner has been soft-deleted
678	     */
679	    public boolean isDeleted() {
680	        return this.deleted;
681	    }
682	
683	    public void setDeleted(boolean deleted) {
684	        this.deleted = deleted;
685	    }
686	
687	    /**
688	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
689	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
690	     */
691	    @PrePersist
692	    void onCreate() {
693	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
694	    }
695	
696	    /**
697	     * Resolves the effective registration date and rolls it onto a business day. An absent
698	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
699	     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
700	     * holiday: starting from the effective date, the date advances one day at a time while it lands
701	     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
702	     * non-holiday business day. A date already on a business day is returned unchanged.
703	     *
704	     * <p>This is the single definition of both the defaulting and the business-day roll, used
705	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
706	     * stamps the owner and by the create endpoint that counts owners per business day.
707	     *
708	     * @param supplied the registration date from the request, or {@code null} when none was supplied
709	     * @return the effective registration date, guaranteed to fall on a non-holiday business day
710	     */
711	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
712	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
713	        while (!isBusinessDay(effective)) {
714	            effective = effective.plusDays(1);
715	        }
716	        return effective;
717	    }
718	
719	    /**
720	     * The fixed list of public holidays that the registration date rolls past, alongside weekends.
721	     */
722	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
723	        LocalDate.of(2026, 1, 1),
724	        LocalDate.of(2026, 1, 26),
725	        LocalDate.of(2026, 4, 25),
726	        LocalDate.of(2026, 12, 25),
727	        LocalDate.of(2026, 12, 28));
728	
729	    /**
730	     * A business day is any date that is neither a weekend day nor a listed public holiday.
731	     */
732	    private static boolean isBusinessDay(LocalDate date) {
733	        DayOfWeek day = date.getDayOfWeek();
734	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
735	    }
736	
737	    protected Set<Pet> getPetsInternal() {
738	        if (this.pets == null) {
739	            this.pets = new HashSet<>();
740	        }
741	        return this.pets;
742	    }
743	
744	    protected void setPetsInternal(Set<Pet> pets) {
745	        this.pets = pets;
746	    }
747	
748	    public List<Pet> getPets() {
749	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
750	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
751	        return Collections.unmodifiableList(sortedPets);
752	    }
753	
754	    public void setPets(List<Pet> pets) {
755	        this.pets = new HashSet<>(pets);
756	    }
757	
758	    public void addPet(Pet pet) {
759	        getPetsInternal().add(pet);
760	        pet.setOwner(this);
761	    }
762	
763	    /**
764	     * Return the Pet with the given name, or null if none found for this Owner.
765	     *
766	     * @param name to test
767	     * @return true if pet name is already in use
768	     */
769	    public Pet getPet(String name) {
770	        return getPet(name, false);
771	    }
772	
773	    /**
774	     * Return the Pet with the given name, or null if none found for this Owner.
775	     *
776	     * @param name to test
777	     * @return true if pet name is already in use
778	     */
779	    public Pet getPet(String name, boolean ignoreNew) {
780	        name = name.toLowerCase();
781	        for (Pet pet : getPetsInternal()) {
782	            if (!ignoreNew || !pet.isNew()) {
783	                String compName = pet.getName();
784	                compName = compName.toLowerCase();
785	                if (compName.equals(name)) {
786	                    return pet;
787	                }
788	            }
789	        }
790	        return null;
791	    }
792	
793	    public Pet getPet(Integer petId) {
794	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
795	    }
796	
797	    @Override
798	    public String toString() {
799	        return new ToStringCreator(this)
800	
801	            .append("id", this.getId())
802	            .append("new", this.isNew())
803	            .append("lastName", this.getLastName())
804	            .append("firstName", this.getFirstName())
805	            .append("address", this.address)
806	            .append("city", this.city)
807	            .append("telephone", this.telephone)
808	            .toString();
809	    }
810	}
