/**
 * The owner's identity key, the single derived value used for duplicate detection. It is the
 * lower-case SHA-256 hex digest (64 characters) of the owner's normalized telephone, lower-cased
 * email (empty when absent) and the {@linkplain #soundex(String) Soundex} of its last name,
 * joined with {@code '|'} ({@code sha256hex('<telephone>|<lowerEmail>|<soundex(lastName)>')}); any
 * absent ({@code null}) component contributes an empty string before hashing. Two owners are
 * duplicates exactly when their whole identity keys are equal, so two owners sharing a last name
 * (and its Soundex) and postcode but carrying different telephones differ here and are both
 * allowed (the second is flagged a soft match rather than rejected).
 *
 * @return the derived identity key, a 64-character lower-case hex string
 */
public String getIdentityKey() {
    String normalizedTelephone = this.telephone == null ? "" : this.telephone;
    String lowerEmail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
    String raw = normalizedTelephone + "|" + lowerEmail + "|" + soundex(this.getLastName());
    return sha256HexLower(raw);
}

/**
 * Maps each letter {@code A}-{@code Z} to its American Soundex code digit, where {@code '0'}
 * marks the non-coded letters (the vowels plus {@code H}, {@code W} and {@code Y}). Indexed by
 * {@code letter - 'A'}.
 */
private static final char[] SOUNDEX_MAPPING = "01230120022455012623010202".toCharArray();

/**
 * The American Soundex code of a name: its first letter followed by three code digits derived
 * from the remaining letters (B/F/P/V=1, C/G/J/K/Q/S/X/Z=2, D/T=3, L=4, M/N=5, R=6; the vowels
 * plus H, W and Y are not coded), right-padded with zeros to exactly four characters. Adjacent
 * letters sharing a code (including when separated only by H or W) contribute a single digit,
 * while letters separated by a vowel are coded twice. Non-letters are ignored and the comparison
 * is case-insensitive. A {@code null} or letter-free value yields an empty string.
 *
 * @param value the name to encode, possibly {@code null}
 * @return the four-character Soundex code, or an empty string when there are no letters
 */
public static String soundex(String value) {
    if (value == null) {
        return "";
    }
    String clean = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
    if (clean.isEmpty()) {
        return "";
    }
    char[] out = {'0', '0', '0', '0'};
    out[0] = clean.charAt(0);
    char last = soundexCode(clean, 0);
    int count = 1;
    for (int i = 1; i < clean.length() && count < out.length; i++) {
        char mapped = soundexCode(clean, i);
        if (mapped != 0) {
            if (mapped != '0' && mapped != last) {
                out[count++] = mapped;
            }
            last = mapped;
        }
    }
    return new String(out);
}

/**
 * The Soundex code digit of the letter at {@code index}, applying the H/W rule: a letter whose
 * code matches the letter two positions back is suppressed (returns {@code (char) 0}) when the
 * intervening letter is {@code H} or {@code W}, so such a pair contributes a single digit.
 *
 * @param str a cleaned, upper-case, letters-only name
 * @param index the position of the letter to code
 * @return the mapped code digit, or {@code (char) 0} when the letter is suppressed by the H/W rule
 */
private static char soundexCode(String str, int index) {
    char mapped = SOUNDEX_MAPPING[str.charAt(index) - 'A'];
    if (index > 1 && mapped != '0') {
        char hw = str.charAt(index - 1);
        if (hw == 'H' || hw == 'W') {
            char preHW = str.charAt(index - 2);
            if (SOUNDEX_MAPPING[preHW - 'A'] == mapped || preHW == 'H' || preHW == 'W') {
                return 0;
            }
        }
    }
    return mapped;
}

/**
 * The full lower-case SHA-256 hex digest (64 characters) of the given value's UTF-8 bytes, the
 * form the {@linkplain #getIdentityKey() identity key} takes.
 *
 * @param value the value to hash
 * @return the 64-character lower-case hex SHA-256 digest
 */
private static String sha256HexLower(String value) {
    try {
        byte[] digest = MessageDigest.getInstance("SHA-256")
            .digest(value.getBytes(StandardCharsets.UTF_8));
        StringBuilder hex = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            hex.append(String.format("%02x", b));
        }
        return hex.toString();
    }
    catch (NoSuchAlgorithmException e) {
        throw new IllegalStateException("SHA-256 algorithm not available", e);
    }
}

